import marimo

__generated_with = "0.24.0"
app = marimo.App()


@app.cell
def _():
    import sympy as sp
    from sympy import diff, exp, expand, factor, integrate, lambdify, oo, series, simplify, sin, solve, symbols
    from sympy.physics.hydrogen import R_nl
    import numpy as np
    import matplotlib.pyplot as plt
    plt.rcParams["figure.dpi"] = 150
    return (
        R_nl,
        diff,
        exp,
        expand,
        factor,
        integrate,
        lambdify,
        np,
        oo,
        plt,
        series,
        simplify,
        sin,
        solve,
        sp,
        symbols,
    )


@app.cell
def _(symbols):
    x, y, a, b = symbols('x y a b')
    x
    return (x,)


@app.cell
def _(expand, x):
    expand((x + 1) * (x + 2) * (x + 3))
    return


@app.cell
def _(factor, x):
    factor(x**3 + 6 * x**2 + 11 * x + 6)
    return


@app.cell
def _(simplify, x):
    simplify((x**3 + x**2 - x - 1) / (x**2 + 2 * x + 1))
    return


@app.cell
def _(solve, x):
    solve(x**2 + 1.4 * x - 5.76, x)
    return


@app.cell
def _(diff, exp, sin, x):
    diff(sin(x) * exp(-x), x)
    return


@app.cell
def _(diff, x):
    diff(x**4, x, 2)   # second derivative
    return


@app.cell
def _(exp, integrate, x):
    integrate(x * exp(-x), x)
    return


@app.cell
def _(exp, integrate, oo, x):
    integrate(exp(-x**2), (x, -oo, oo))
    return


@app.cell
def _(exp, series, x):
    series(exp(x), x, 0, 6)
    return


@app.cell
def _(R_nl, symbols):
    r = symbols('r', positive=True)
    R_21 = R_nl(n=2, l=1, r=r, Z=1)
    R_21
    return R_21, r


@app.cell
def _(R_21, diff, r, solve):
    # radius of maximum radial probability: solve d/dr [ r^2 R^2 ] = 0
    density = r**2 * R_21**2
    r_max = float(max(solve(diff(density, r), r)))   # largest (nonzero) root
    r_max
    return density, r_max


@app.cell
def _(density, lambdify, np, plt, r, r_max):
    f = lambdify(r, density, modules='numpy')
    rr = np.linspace(0, 20, 200)

    plt.plot(rr, f(rr))
    plt.axvline(r_max, color='r', ls='--', label=f'peak at r = {r_max:.1f} a0')
    plt.xlabel('radius r  ($a_0$)')
    plt.ylabel('radial probability density  $r^2 R^2$')
    plt.legend()
    return


@app.cell
def _(sp):
    x = sp.symbols("x")
    sp.integrate(sp.sin(x) ** 2, (x, 0, sp.pi))   # try your own integral
    return (x,)


